\label{thm:full}\label{thm:main}
Let $n\ge2$, $0<m\le n-1$, $2\le p\le q_n$, and $3\le k\le n+1$. If $H$ satisfies \eqref{eq:weight}, then for every $\varepsilon>0$,
\begin{equation}\label{eq:full}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,m,p,k,\varepsilon} C_H^{1/p}
 R^{\max\{A_{n,m,k}(p),N_{n,m,k}(p),C_{n,m}(p)\}+\varepsilon}
 \left\lVert f\right\rVert_{2}.
\end{equation}
The constant is independent of $R\ge1$, the center of $B_R$, $f$, and $H$. For $p\ge q_n$, the exponent of $R$ can be taken to be zero, without an $R^\varepsilon$ loss.

\label{cor:measure}
Let $\mu$ be a nonnegative locally finite Borel measure on $\mathbb{R}^{n+1}$ satisfying
\begin{equation}\label{eq:measure-weight}
 \mu(B(z,r))\le C_\mu r^m
 \qquad(z\in\mathbb{R}^{n+1},\ 1\le r\le R^{1/2}).
\end{equation}
Under the parameter assumptions of Theorem~\ref{thm:full},
\begin{equation}\label{eq:measure-upper}
 \left\lVert Ef\right\rVert_{L^p(B_R,d\mu)}
 \lesssim_{n,m,p,\varepsilon}
 C_\mu^{1/p}R^{B_{n,m}(p)+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}
The loss $R^\varepsilon$ is unnecessary for $p\ge q_n$. No condition at radii below $1$ is required.

\label{cor:small-p-general}
Set
\begin{equation}\label{eq:small-p-general-endpoint}
 a^*_{n,m}=\min\left\{\frac{n-m}{n^2(n+1)},\frac1{(n+1)^2}\right\},
 \qquad p_{n,m}=\left(\frac12-a^*_{n,m}\right)^{-1}.
\end{equation}
For $2\le p\le p_{n,m}$,
\begin{equation}\label{eq:small-p-general}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,m,p,\varepsilon}C_H^{1/p}
 R^{\frac{n+1+m}{2}(\frac1p-\frac12)
       +\frac{m+1}{2(n+1)}+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}
If $1\le m\le n-1$, then
\[
 p_{n,m}=\left(\frac12-\frac{n-m}{n^2(n+1)}\right)^{-1}.
\]

\label{cor:clean}
Let $n\ge3$, assume $m=n-1$, and set
\begin{equation}\label{eq:clean-endpoint}
 k_0=\left\lfloor\frac{n+3}{2}\right\rfloor,
 \qquad p_0=\frac{2k_0(n+1)}{k_0(n+1)-2}.
\end{equation}
For $p_0\le p\le q_n$,
\begin{equation}\label{eq:clean}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,p,\varepsilon} C_H^{1/p}
 R^{\frac{n-1}{2}(\frac1p-\frac1{q_n})+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}
In particular, in $\mathbb{R}^4$, for two-dimensional weights,
\begin{equation}\label{eq:R4}
 \left\lVert Ef\right\rVert_{L^{12/5}(B_R,H)}
 \lesssim_\varepsilon C_H^{5/12}R^{1/6+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}

\label{cor:sharp-R3}
Suppose $n=2$, $2/3\le m\le1$, and
\begin{equation}\label{eq:sharp-R3-range}
 \frac{12}{m+4}\le p\le\frac6{3-m}.
\end{equation}
Then
\begin{equation}\label{eq:sharp-R3}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{m,p,\varepsilon} C_H^{1/p}
 R^{\frac{m+1}{2p}-\frac14+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}
The exponent $(m+1)/(2p)-1/4$ is sharp up to $R^\varepsilon$. In particular, for $m=1$ this gives the sharp exponent $1/p-1/4$ on $12/5\le p\le3$.

\label{cor:variety}
Let $0<m\le n-1$ and $2\le\ell\le n+1$. Suppose that $Z\subset\mathbb{R}^{n+1}$ is an $\ell$-dimensional transverse complete intersection with defining degrees at most $D\ge1$. Let $E\ge1$, and suppose that, in $B_R$, $Ef$ is supported in $\mathcal N_{E\sqrt R}(Z)$ up to a rapidly decaying error. Define
\begin{equation}\label{eq:safe}
 B_{n,m,\ell}^{\mathrm{safe}}(p)
 =\inf_{p\le s\le q_n}
 \left[B_{n,m}(s)+\frac{\ell+m}{2}\left(\frac1p-\frac1s\right)\right].
\end{equation}
For $2\le p\le q_n$,
\begin{equation}\label{eq:variety}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,m,p,\varepsilon} C_H^{1/p}D^{O(1)}E^{O(1)}
 R^{B_{n,m,\ell}^{\mathrm{safe}}(p)+\varepsilon}\left\lVert f\right\rVert_{2}.
\end{equation}

\label{thm:plane}
Assume $m=n-1$. Let $3\le\ell\le n+1$ and let $V$ be a fixed affine $\ell$-plane whose direction space satisfies $\chi(V)\ge\chi_0>0$; this assumption is omitted when $\ell=n+1$.
Let $0<\delta\ll\varepsilon$ and $E\ge R^\delta$. Suppose that $f$ is concentrated in the usual scale-$R$ wave packets that are $ER^{-1/2}$-tangent to $V$. Then, for $2\le p\le q_{\ell-1}$,
\begin{equation}\label{eq:plane-general}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,\ell,p,\varepsilon,\chi_0} C_H^{1/p}E^{O(1)}
 R^{B_{\ell-1}(p)+\frac{n+1-\ell}{2}(\frac1p-\frac12)+\varepsilon}
 \left\lVert f\right\rVert_{2},
\end{equation}
where $B_{\ell-1}=B_{\ell-1,\ell-2}$ as in \eqref{eq:special-notation}. In particular, with
\begin{equation}\label{eq:plane-endpoint}
 p_\ell^{\mathrm c}
 =\left(\frac12-\frac1{\ell(\ell-1)^2}\right)^{-1},
\end{equation}
one has, for $2\le p\le p_\ell^{\mathrm c}$,
\begin{equation}\label{eq:plane-main}
 \left\lVert Ef\right\rVert_{L^p(B_R,H)}
 \lesssim_{n,\ell,p,\varepsilon,\chi_0} C_H^{1/p}E^{O(1)}
 R^{\frac{n+\ell-1}{2}(\frac1p-\frac12)+\frac{\ell-1}{2\ell}+\varepsilon}
 \left\lVert f\right\rVert_{2}.
\end{equation}

\label{lem:translations}
Let $2\le k\le n+1$, $0<q<\infty$, and $q\le r\le\infty$. There is a fixed lattice spacing $a_0>0$ such that, for a cube $B$ of side $K^2$ and inputs $f_1,\ldots,f_k$, one can choose
\[
 v_j\in a_0\mathbb Z^{n+1},\qquad |v_j|\lesssim K^2,
 \qquad j=1,\ldots,k,
\]
with
\begin{equation}\label{eq:translation-product}
 \prod_{j=1}^k\left\lVert Ef_j\right\rVert_{L^r(B)}^{1/k}
 \lesssim K^{O(1)}
 \left\|\prod_{j=1}^k|Ef_j(\,\cdot+v_j)|^{1/k}\right\|_{L^q(B)}
 +\operatorname{RapDec}(R)\prod_{j=1}^k\left\lVert f_j\right\rVert_{2}^{1/k}.
\end{equation}
There are $K^{O(1)}$ possible translation tuples.

\label{thm:multilinear}
Let $q=2(n+1)/(n-1)$ and $2\le k\le n+1$. Suppose that $f_1,\ldots,f_k$ are $\nu$-transverse and that $\mathcal Q$ is a family of $N$ lattice $R^{1/2}$-cubes in $B_R$. Assume that for each $j$, the quantities $\left\lVert Ef_j\right\rVert_{L^q(Q)}$ are dyadically constant as $Q$ varies over $\mathcal Q$. Then
\begin{equation}\label{eq:multi}
 \left\|\prod_{j=1}^k|Ef_j|^{1/k}\right\|_{L^q(\bigcup\mathcal Q)}
 \lesssim_\eta \nu^{-O(1)}R^\eta N^{-b_k}
                  \prod_{j=1}^k\left\lVert f_j\right\rVert_{2}^{1/k},
 \qquad b_k=\frac{k-1}{k(n+1)}.
\end{equation}
Here $\eta>0$ is arbitrary; fixed cone charts and fixed enlargements of the cubes are allowed.

\label{thm:decoupling}
Let $k\ge3$, $r=2(k-1)/(k-3)$, and $F=\sum_\tau F_\tau$, where each $\widehat F_\tau$ is supported in an $O(K^{-2})$-neighborhood of a $K^{-1}$-cap. Suppose there is a $(k-1)$-plane $V$ such that each cap contains a point with normal at distance $O(K^{-2})$ from $V$. For $2\le s\le r$, $s<\infty$,
\begin{equation}\label{eq:decoupling-input}
 \left\lVert F\right\rVert_{L^s(B)}\lesssim_\eta K^\eta
       \left(\sum_\tau\left\lVert F_\tau\right\rVert_{L^s(w_B)}^2\right)^{1/2},
\end{equation}
where $B$ has side $K^2$, $\eta>0$, and the adapted weight satisfies
\[
 w_B(z)\lesssim_{N_0}
      \bigl(1+K^{-2}|z-c_B|\bigr)^{-N_0}.
\]
The decay order $N_0$ may be chosen sufficiently large in terms of the fixed parameters. When $k=3$, there are only $O(1)$ relevant caps, and the endpoint $s=\infty$ holds with $L^\infty(B)$ on both sides.

\label{prop:discrete}
Fix $n,m,p,k$ as in Theorem~\ref{thm:full}, and let $r,t$ be given by \eqref{eq:r}. Put
\[
 \beta=\max\{A_{n,m,k}(p),N_{n,m,k}(p),C_{n,m}(p)\}.
\]
For every $\varepsilon>0$, one can choose $\delta>0$ sufficiently small so that the following holds for every $R\ge1$, with $K=R^\delta$. Suppose that $Y$ consists of $M$ lattice $K^2$-cubes and that
\begin{equation}\label{eq:equal-old}
 \Lambda\le\left\lVert Ef\right\rVert_{L^r(B)}<2\Lambda
 \qquad(B\subset Y)
\end{equation}
for some $\Lambda>0$. Then
\begin{equation}\label{eq:discrete}
 \left\lVert Ef\right\rVert_{L^r(Y)}
 \le C_\varepsilon R^{\beta+\varepsilon}
          \left(\frac{\gamma(Y)}M\right)^t\left\lVert f\right\rVert_{2}.
\end{equation}
The same assertion holds in the fixed cone charts of Section~\ref{subsec:charts} and for the fixed lattice variants described above.

\label{prop:lower-bounds}
Let $n\ge2$ and $0<m\le n-1$. Any exponent $\beta$ in \eqref{eq:necessary-assumption} satisfies
\begin{equation}\label{eq:universal-lower}
 \beta\ge\max\{0,P_{n,m}(p)\}.
\end{equation}
If $n\ge3$ and $(n+1)/2\le m\le n-1$, it also satisfies $\beta\ge L_{n,m}(p)$. For every $j\in\mathcal J_{n,m}$,
\begin{equation}\label{eq:hybrid-lower}
 \beta\ge\mathfrak b_{n,m,j}(p).
\end{equation}
In particular, taking $j=0$ extends the lattice obstruction $L_{n,m}$ to every $0<m\le n-1$ when $n\ge4$.

\label{lem:integer-cone}
For $d\ge4$ and every sufficiently large integer $Q$, there is a set
\begin{equation}\label{eq:integer-cone-set}
 \mathcal P_Q\subseteq
 \{(h,b)\in\mathbb Z^d\times\mathbb Z:
      |h|^2=b^2,\ 5Q/4\le b\le3Q/2\}
\end{equation}
with $\#\mathcal P_Q\sim Q^{d-1}$.
